import sys

def solve():
    s = sys.stdin.readline().strip()
    if not s:
        print(-1)
        return

    max_len = 0
    stack = [-1]

    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                current_len = i - stack[-1]
                if current_len > max_len:
                    max_len = current_len

    if max_len > 0:
        print(max_len)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
